/* ============================================================
   api/server.js — „Programul de Azi”
   Server Express, compatibil Vercel Serverless Functions.
   Rute:
     GET /:oras/:magazin   -> pagină cu status live pentru un magazin dintr-un oraș
     GET /:oras            -> pagină generală: listă de magazine pentru orașul respectiv
   ============================================================ */

const express = require("express");
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const { Pool } = require("pg");
// put() e funcția standard, server-side, a @vercel/blob — trimite bytes-ii
// prin funcția noastră Express (limitată la ~4MB per poză, ca orice request
// pe Vercel), dar fără adaptorul fragil peste `req` pe care-l necesita
// varianta anterioară (handleUpload, gândită pentru Next.js). import()
// dinamic, la fel ca înainte, ca să meargă indiferent de tipul de pachet.
let blobPutPromise = null;
function getBlobPut() {
  if (!blobPutPromise) {
    blobPutPromise = import("@vercel/blob")
      .then((m) => m.put)
      .catch((err) => {
        console.warn("Nu am putut încărca @vercel/blob:", err.message);
        return null;
      });
  }
  return blobPutPromise;
}
const app = express();

// ============================================================
// Webhook Stripe — TREBUIE înregistrat AICI, înaintea parserului JSON
// global de mai jos (`app.use(express.json(...))`) — verificarea semnăturii
// Stripe are nevoie de bytes-ii bruti, nemodificați, ai request-ului; dacă
// json() îl parsează primul, semnătura nu se mai poate verifica niciodată.
// `stripeClient` e asignat mai jos, după ce STRIPE_SECRET_KEY e citit din
// mediu — `let`, nu `const`, exact ca să poată fi completat mai târziu, dar
// referit aici, în closure (la momentul unei cereri reale, e deja asignat).
// ============================================================
let stripeClient = null;
app.post("/api/webhooks/stripe", express.raw({ type: "application/json" }), async (req, res) => {
  if (!stripeClient || !STRIPE_WEBHOOK_SECRET) { res.status(503).send("not_configured"); return; }
  let event;
  try {
    event = stripeClient.webhooks.constructEvent(req.body, req.headers["stripe-signature"], STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    console.error("Stripe webhook — semnătură invalidă:", err.message);
    res.status(400).send(`Webhook Error: ${err.message}`);
    return;
  }
  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const listingId = session.metadata && session.metadata.listingId;
    if (listingId && dbPool) {
      try {
        if (session.mode === "subscription") {
          // Abonament nou activat — reținem ID-urile Stripe, ca să putem
          // sincroniza starea ulterior (webhook-urile de mai jos) și ca
          // să putem deschide Portalul de facturare pentru acest client.
          await dbPool.query(
            `UPDATE accommodation_listings SET stripe_subscription_id = $1, stripe_customer_id = $2, subscription_status = 'trial'
             WHERE id = $3`,
            [session.subscription, session.customer, listingId]
          );
        } else {
          // Featured — plată unică, neschimbat față de înainte.
          await dbPool.query(
            `UPDATE accommodation_listings
             SET featured_until = GREATEST(COALESCE(featured_until, now()), now()) + interval '1 day' * $2
             WHERE id = $1`,
            [listingId, ACCOMMODATION_FEATURED_DURATION_DAYS]
          );
        }
      } catch (err) {
        console.error("checkout.session.completed a eșuat:", err.message);
      }
    }
  }
  // Sincronizare status abonament — Stripe e sursa de adevăr; noi doar
  // oglindim starea, ca site-ul public să știe cine rămâne vizibil.
  // Mapare: trialing->trial, active->active, past_due->past_due,
  // canceled/unpaid->canceled (delistat de pe site, dar nu șters).
  if (event.type === "customer.subscription.updated" || event.type === "customer.subscription.deleted") {
    const sub = event.data.object;
    const statusMap = { trialing: "trial", active: "active", past_due: "past_due", canceled: "canceled", unpaid: "canceled", incomplete_expired: "canceled" };
    const newStatus = statusMap[sub.status] || "canceled";
    if (dbPool) {
      try {
        await dbPool.query(`UPDATE accommodation_listings SET subscription_status = $1 WHERE stripe_subscription_id = $2`, [newStatus, sub.id]);
      } catch (err) {
        console.error("sincronizare abonament a eșuat:", err.message);
      }
    }
  }
  res.status(200).json({ received: true });
});
app.use(express.json({ limit: "16kb" })); // necesar pentru rutele de abonare push (POST cu JSON în body)

// ============================================================
// CONSOLIDARE .ro -> .eu (Redirecționare 301 permanentă) — comutator
// central, DEZACTIVAT implicit. Când e pus pe true, TOATE paginile de pe
// programul-de-azi.ro redirecționează permanent (301) către echivalentul
// lor de pe opening-hours-today.eu/ro/... . AdSense scos complet din site
// (decizie separată, nemaifiind un blocaj), Travelpayouts confirmat pe
// ambele domenii — nu mai există motiv să amânăm.
//
// Excepții, care NU se redirecționează (rămân active pe .ro, chiar și cu
// comutatorul pornit): /api/*, fișierele tehnice (manifest, service worker,
// iconițe) și robots.txt/ads.txt/sitemap.xml — astea trebuie să rămână
// accesibile, ca Google/crawlerele să vadă corect tranziția, nu erori.
//
// Ghidurile sunt un caz SPECIAL — conținut complet diferit, în rute
// SEPARATE pe .eu (/guides/*, engleză, nu /ro/ghiduri/*, care nu există)
// — bug real, prins prin testare, înainte de activare, nu doar teoretic.
const RO_TO_EU_MIGRATION_ACTIVE = true;
const RO_TO_EU_MIGRATION_EXCLUDED_PREFIXES = ["/api/", "/manifest.json", "/sw.js", "/robots.txt", "/ads.txt", "/sitemap.xml", "/icon.svg", "/icon-512.png", "/icon-192.png", "/favicon.ico", "/style.css", "/badge.js", "/cad147c6a5b6cb338e880ca855c2679f.html", "/2697e31851e3c90a2ff17b8730d67b88.html", "/itinerar", "/propune", "/admin", "/cazare", "/cont"];
const RO_TO_EU_GUIDES_MAP = { "/ghiduri": "/guides", "/ghiduri/transport": "/guides/transport", "/ghiduri/parcari": "/guides/parking", "/ghiduri/restaurante": "/guides/restaurants" };
app.use((req, res, next) => {
  if (!RO_TO_EU_MIGRATION_ACTIVE || isIntlHost(req)) return next();
  if (RO_TO_EU_MIGRATION_EXCLUDED_PREFIXES.some((p) => req.path === p || req.path.startsWith(p))) return next();
  if (RO_TO_EU_GUIDES_MAP[req.path]) {
    return res.redirect(301, `https://${INTL_DOMAIN}${RO_TO_EU_GUIDES_MAP[req.path]}`);
  }
  const target = req.path === "/" ? `https://${INTL_DOMAIN}/` : `https://${INTL_DOMAIN}/ro${req.path}`;
  return res.redirect(301, target);
});

// Antete de securitate HTTP, aplicate O SINGURĂ DATĂ, pe toate răspunsurile —
// mai sigur decât să le repeți în fiecare rută (unde ar fi ușor să uiți una).
// CSP rămâne separat, per-rută, pentru că are nevoie de nonce unic per pagină.
app.use((req, res, next) => {
  res.set("X-Content-Type-Options", "nosniff"); // browserul nu "ghicește" tipul unui fișier, doar pe baza extensiei
  // Testul cu iframe s-a încheiat — Travelpayouts a confirmat cauza reală
  // (connect-src, nu iframe/frame-ancestors) — restaurăm protecția.
  res.set("X-Frame-Options", "DENY");
  res.set("Referrer-Policy", "no-referrer-when-downgrade"); // TEST: strict-origin-when-cross-origin trimitea doar originea (fără cale) către alte site-uri — ipoteză: Travelpayouts se bazează pe URL-ul complet ca să identifice contul corect de furnizor, de-aia widget-ul mergea perfect pe pagina de test (fără nicio restricție), dar eșua ("Provider's accounts list is empty") pe pagina reală. Rămâne totuși mai sigur decât "unsafe-url" — nu trimite deloc referrer la un downgrade HTTPS→HTTP.
  res.set("Strict-Transport-Security", "max-age=63072000; includeSubDomains"); // forțează HTTPS, chiar dacă cineva încearcă explicit http://
  res.set("Permissions-Policy", "geolocation=(self), camera=(), microphone=()"); // geolocația rămâne, restul dezactivat explicit
  next();
});

/* ============================================================
   0.05) STATUS LIVE (Google Places) — conexiune OPȚIONALĂ la baza de
   date. Dacă lipsește variabila de mediu (POSTGRES_URL/DATABASE_URL) sau
   baza pică, site-ul TOT funcționează — doar cade elegant pe orele fixe,
   deja verificate, care au funcționat până acum. Nicio pagină nu depinde
   STRICT de conexiunea asta ca să se afișeze.
   ============================================================ */
const DB_CONNECTION_STRING =
  process.env.POSTGRES_URL || process.env.DATABASE_URL || process.env.POSTGRES_PRISMA_URL || "";
// Cheie secretă pentru pagina de administrare (/admin/propuneri) — setează-o
// ca variabilă de mediu în Vercel (ADMIN_SECRET_KEY), NU o pune direct în
// cod. Fără ea setată, pagina rămâne complet inaccesibilă (fail-safe, nu
// fail-open) — mai sigur decât o parolă implicită ghicibilă.
const ADMIN_SECRET_KEY = process.env.ADMIN_SECRET_KEY || "";
// Secțiunea "Cazare" (director pensiuni/cazări mici) — funcționalitate NOUĂ,
// în construcție. Rămâne complet ascunsă (404 pentru oricine) cât timp
// ACCOMMODATION_LIVE nu e explicit "true" în Vercel — la fel, fail-safe.
// Link de test intern: /cazare?preview=CHEIA_TA (setează cookie, nu mai
// trebuie repetat parametrul). Când totul e gata, flip pe ACCOMMODATION_LIVE=true
// și dispare gate-ul peste tot, dintr-o mișcare, fără alte modificări.
const ACCOMMODATION_PREVIEW_KEY = process.env.ACCOMMODATION_PREVIEW_KEY || "";
const ACCOMMODATION_LIVE = process.env.ACCOMMODATION_LIVE === "true";
const RESEND_API_KEY = process.env.RESEND_API_KEY || "";
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY || "";
const STRIPE_WEBHOOK_SECRET = process.env.STRIPE_WEBHOOK_SECRET || "";
try {
  stripeClient = STRIPE_SECRET_KEY ? require("stripe")(STRIPE_SECRET_KEY) : null;
} catch (e) {
  console.warn("Pachetul `stripe` nu e instalat — plățile Featured indisponibile până la `npm install`.");
}
// Pachetul Featured — preț fix, plată unică (NU abonament recurent, ca să nu
// gestionăm reînnoiri/eșecuri de plată automate). Ușor de schimbat aici,
// într-un singur loc.
const ACCOMMODATION_FEATURED_PRICE_CENTS = 4500; // 45,00 EUR
const ACCOMMODATION_FEATURED_DURATION_DAYS = 90; // ~3 luni
// Abonament lunar de bază — DIFERIT de Featured (de mai sus). Prețul NU e
// hardcodat aici — se citește din DB (accommodation_settings), editabil din
// /admin/setari, fără redeploy. 0 = neconfigurat încă, tratat ca "gratuit"
// (nu forțăm nimic la plată până admin pune un preț real).
const ACCOMMODATION_TRIAL_MONTHS = 3;
// Cât de des scriem efectiv contorul de vizualizări în bază — 1 din N
// vizualizări, cerut explicit ca să reducem conexiunile către Neon (plan
// gratuit, limitat la ore de compute activ). Vezi comentariul de lângă
// folosire — media rămâne corectă, doar frecvența scrierilor scade.
const VIEWS_SAMPLE_RATE = 4;
// Link-ul de widget Aviasales, folosit de butonul "✈️ Zboruri" din
// sub-navigare — comun pe pagina de director și pe cea a proprietății.
const AVIASALES_SRC = "https://tpembd.com/content?currency=eur&trs=565241&shmarker=767825&show_hotels=true&powered_by=true&locale=en&searchUrl=www.aviasales.com%2Fsearch&primary_override=%2332a8dd&color_button=%23F0813A&color_icons=%2332a8dd&dark=%23262626&light=%23FFFFFF&secondary=%23FFFFFF&special=%23C4C4C4&color_focused=%2332a8dd&border_radius=12&no_labels=&plain=true&promo_id=7879&campaign_id=100";
// Widget transferuri (aeroport etc.) — TravelPayouts, program intui.travel.
// promo_id=4674/campaign_id=22 — același widget deja folosit și pe paginile
