const linkGlovoAffiliate = ""; // dacă rămâne gol, cade pe glovoapp.com (link public, funcțional, fără tracking)
const linkBringoAffiliate = ""; // dacă rămâne gol, cade pe bringo.ro (link public, funcțional, fără tracking)
