function bookingSearchLinkFor(place) {
  const base = `https://www.booking.com/searchresults.html?ss=${encodeURIComponent(place)}`;
  return BOOKING_AFFILIATE_ID ? `${base}&aid=${encodeURIComponent(BOOKING_AFFILIATE_ID)}` : base;
}

