  "baneasa-shopping-city": { key: "mall", displayName: "Băneasa Shopping City" },
  "parklake": { key: "mall", displayName: "ParkLake" },
  "mega-mall": { key: "mall", displayName: "Mega Mall" },
  "sun-plaza": { key: "mall", displayName: "Sun Plaza" },
