app.get("/admin/propuneri", async (req, res) => {
  if (!requireAdminPage(req, res)) return;
  if (!dbPool) {
    res.status(503).send("Baza de date nu e configurată.");
    return;
  }
  let rows = [];
  try {
    const result = await dbPool.query(
      `SELECT id, type, name, city, country_code, category, maps_url, note, schedule, other_type, submission_count, creat_la
       FROM pending_submissions WHERE status = 'pending' ORDER BY submission_count DESC, creat_la ASC`
    );
    rows = result.rows;
  } catch (err) {
    res.status(500).send("Eroare la citirea propunerilor: " + escapeHtml(err.message));
    return;
  }
  const typeLabels = { store: "🛒 Magazin", attraction: "🏛️ Obiectiv", beach: "🏖️ Plajă", restaurant: "🍽️ Restaurant", cafe: "☕ Cafenea", other: "📍 Altceva" };
  const scheduleHtmlFor = (raw) => {
    if (!raw) return "";
    let sch; try { sch = typeof raw === "string" ? JSON.parse(raw) : raw; } catch (e) { return ""; }
    if (!sch) return "";
    if (sch.is247) return `<p class="admin-submission-schedule">🕐 Deschis non-stop (24/7)</p>`;
    if (!sch.days) return "";
    const rows = SUBMIT_PLACE_SCHEDULE_DAYS.map((d) => {
      const day = sch.days[String(d.idx)];
      if (!day) return null;
      return `${escapeHtml(DAY_NAMES[d.idx])}: ${day.closed ? "închis" : escapeHtml(day.open) + "–" + escapeHtml(day.close)}`;
    }).filter(Boolean);
    return rows.length ? `<p class="admin-submission-schedule">🕐 ${rows.join(" · ")}</p>` : "";
  };
  const rowsHtml = rows.length
    ? rows.map((r) => `
      <div class="admin-submission-card">
        <div class="admin-submission-header">
          <span class="admin-submission-type">${escapeHtml(r.type === "other" && r.other_type ? "📍 " + r.other_type : (typeLabels[r.type] || r.type))}</span>
          ${r.submission_count > 1 ? `<span class="admin-submission-count">👥 ${r.submission_count}× propus</span>` : ""}
        </div>
        <div class="admin-submission-name">${escapeHtml(r.name)}</div>
        <div class="admin-submission-meta">${escapeHtml(r.city)}, ${escapeHtml(COUNTRY_LABELS[r.country_code] || r.country_code)}${r.category ? " · " + escapeHtml(r.category) : ""}</div>
        ${r.maps_url ? `<a href="${escapeHtml(r.maps_url)}" target="_blank" rel="noopener">📍 Vezi pe hartă</a>` : ""}
        ${scheduleHtmlFor(r.schedule)}
        ${r.note ? `<p class="admin-submission-note">${escapeHtml(r.note)}</p>` : ""}
        <div class="admin-submission-actions">
          <button type="button" class="admin-approve-btn" data-id="${r.id}">✓ Aprobă</button>
          <button type="button" class="admin-reject-btn" data-id="${r.id}">✕ Respinge</button>
        </div>
      </div>`).join("")
    : `<p>Nicio propunere în așteptare momentan.</p>`;

  res.set("Content-Type", "text/html; charset=utf-8");
  res.send(`<!DOCTYPE html>
<html lang="ro"><head><meta charset="UTF-8"><title>Propuneri utilizatori</title>
<style>
body{font-family:sans-serif;max-width:700px;margin:20px auto;padding:0 16px;background:#111;color:#eee;}
.admin-submission-card{background:#1c1c1c;border-radius:10px;padding:16px;margin-bottom:12px;}
.admin-submission-header{display:flex;justify-content:space-between;margin-bottom:6px;}
.admin-submission-type{font-weight:700;}
.admin-submission-count{color:#ff8a3d;font-weight:700;}
.admin-submission-name{font-size:17px;font-weight:700;}
.admin-submission-meta{color:#999;margin:4px 0;}
.admin-submission-note{color:#ccc;font-style:italic;}
.admin-submission-schedule{color:#bbb;font-size:13px;}
.admin-submission-actions{margin-top:10px;display:flex;gap:8px;}
.admin-approve-btn{background:#2e7d32;color:#fff;border:none;border-radius:6px;padding:8px 14px;cursor:pointer;}
.admin-reject-btn{background:#c62828;color:#fff;border:none;border-radius:6px;padding:8px 14px;cursor:pointer;}
</style></head>
<body>
<h1>📋 Propuneri utilizatori (${rows.length})</h1>
${rowsHtml}
<script>
document.querySelectorAll(".admin-approve-btn, .admin-reject-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    var action = btn.classList.contains("admin-approve-btn") ? "aproba" : "respinge";
    fetch("/api/admin/propuneri/" + btn.getAttribute("data-id") + "/" + action, { method: "POST" })
      .then(function(){ btn.closest(".admin-submission-card").remove(); });
  });
});
</script>
</body></html>`);
});

app.post("/api/admin/propuneri/:id/:action", async (req, res) => {
  if (!requireAdminApi(req, res)) return;
  if (!dbPool) {
    res.status(503).json({ error: "not_configured" });
    return;
  }
  const { id, action } = req.params;
  if (!["aproba", "respinge"].includes(action) || !/^\d+$/.test(id)) {
    res.status(400).json({ error: "invalid_input" });
    return;
  }
  const newStatus = action === "aproba" ? "approved" : "rejected";
  try {
    await dbPool.query(`UPDATE pending_submissions SET status = $1, actualizat_la = now() WHERE id = $2`, [newStatus, id]);
    res.status(200).json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "server_error" });
  }
});


app.get("/admin/cazari", async (req, res) => {
  if (!requireAdminPage(req, res)) return;
  if (!dbPool) {
    res.status(503).send("Baza de date nu e configurată.");
    return;
  }
  const validStatuses = ["pending", "approved", "rejected", "all"];
  const activeStatus = validStatuses.includes(req.query.status) ? req.query.status : "pending";
  let rows = [];
  let counts = { pending: 0, approved: 0, rejected: 0 };
  try {
    const result = await dbPool.query(
      `SELECT l.*, o.email AS owner_email FROM accommodation_listings l
       JOIN accommodation_owners o ON o.id = l.owner_id
       ${activeStatus === "all" ? "" : "WHERE l.status = $1"}
       ORDER BY l.actualizat_la DESC`,
      activeStatus === "all" ? [] : [activeStatus]
    );
    rows = result.rows;
    const countsResult = await dbPool.query(
      `SELECT status, COUNT(*)::int AS cnt FROM accommodation_listings GROUP BY status`
    );
    countsResult.rows.forEach((r) => { counts[r.status] = r.cnt; });
  } catch (err) {
    res.status(500).send("Eroare la citirea listărilor: " + escapeHtml(err.message));
    return;
  }
  const statusLabel = { pending: "⏳ În verificare", approved: "✓ Aprobat", rejected: "✕ Respins" };
  const rowsHtml = rows.length
    ? rows.map((r) => {
        const photos = Array.isArray(r.photos) ? r.photos : (typeof r.photos === "string" ? JSON.parse(r.photos) : []);
        const amenities = Array.isArray(r.amenities) ? r.amenities : (typeof r.amenities === "string" ? JSON.parse(r.amenities) : []);
        return `
      <div class="admin-submission-card">
        <div class="admin-submission-header">
          <span class="admin-submission-type">${escapeHtml(r.type === "altceva" && r.other_type ? "📍 " + r.other_type : (ACCOMMODATION_TYPE_LABELS[r.type] || r.type))}</span>
          <span class="admin-status-tag admin-status-${escapeHtml(r.status)}">${escapeHtml(statusLabel[r.status] || r.status)}</span>
        </div>
        <div class="admin-submission-name">${escapeHtml(r.name)}${r.status === "approved" ? ` — <a href="/cazare/${escapeHtml(r.slug)}" target="_blank">vezi pagina live ↗</a>` : ""}</div>
        <div class="admin-submission-meta">${escapeHtml(r.address || "")}, ${escapeHtml(r.city)}, ${escapeHtml(COUNTRY_LABELS[r.country_code] || r.country_code)} · ${r.max_capacity} pers. · ${r.rooms_count || "?"} camere · de la ${r.price_from} ${escapeHtml(r.price_currency)}/noapte</div>
        <div class="admin-submission-meta">Check-in ${escapeHtml(r.checkin_time || "—")} · Check-out ${escapeHtml(r.checkout_time || "—")}</div>
        <div class="admin-submission-meta">Proprietar cont: ${escapeHtml(r.owner_email)} · Tel: ${escapeHtml(r.contact_phone || "—")} · Email: ${escapeHtml(r.contact_email || "—")}</div>
        ${amenities.length || r.other_amenities_text ? `<div class="admin-submission-meta">${[...amenities.map((a) => ACCOMMODATION_AMENITIES[a] || a), r.other_amenities_text].filter(Boolean).map(escapeHtml).join(" · ")}</div>` : ""}
        ${photos.length ? `<div style="display:flex;gap:6px;flex-wrap:wrap;margin:8px 0">${photos.map((p) => `<img src="${escapeHtml(p)}" style="width:70px;height:70px;object-fit:cover;border-radius:6px">`).join("")}</div>` : ""}
        ${r.website_url ? `<a href="${escapeHtml(r.website_url)}" target="_blank" rel="noopener">🌐 Website</a><br>` : ""}
        ${r.booking_profile_url ? `<a href="${escapeHtml(r.booking_profile_url)}" target="_blank" rel="noopener">🔗 Profil existent</a><br>` : ""}
        ${r.facebook_url ? `<a href="${escapeHtml(r.facebook_url)}" target="_blank" rel="noopener">📘 Facebook</a> ` : ""}
        ${r.instagram_url ? `<a href="${escapeHtml(r.instagram_url)}" target="_blank" rel="noopener">📷 Instagram</a> ` : ""}
        ${r.tiktok_url ? `<a href="${escapeHtml(r.tiktok_url)}" target="_blank" rel="noopener">🎵 TikTok</a>` : ""}
        <div class="admin-submission-meta" style="margin-top:8px;border-top:1px solid #333;padding-top:8px">
          <strong>Date fiscale (verificare):</strong><br>
          ${escapeHtml(r.company_name || "—")} · CUI ${escapeHtml(r.company_vat_payer ? "RO" : "")}${escapeHtml(r.company_cui || "—")} (${r.company_vat_payer ? "plătitor TVA" : "neplătitor TVA"})<br>
          Reg. Com.: ${escapeHtml(r.company_reg_com || "—")}<br>
          Sediu: ${escapeHtml(r.company_address || "—")}<br>
          IBAN: ${escapeHtml(r.company_iban || "—")} · ${escapeHtml(r.company_bank || "—")}<br>
          Facturare: ${escapeHtml(r.billing_email || "—")}
        </div>
        ${r.status === "pending" ? `
        <div class="admin-submission-actions">
          <button type="button" class="admin-approve-btn" data-id="${r.id}">✓ Aprobă</button>
          <button type="button" class="admin-reject-btn" data-id="${r.id}">✕ Respinge</button>
          <button type="button" class="admin-delete-btn" data-id="${r.id}" data-name="${escapeHtml(r.name)}">🗑️ Șterge</button>
        </div>` : `
        <div class="admin-submission-actions">
          <button type="button" class="admin-repending-btn" data-id="${r.id}">↺ Repune în verificare</button>
          <button type="button" class="admin-delete-btn" data-id="${r.id}" data-name="${escapeHtml(r.name)}">🗑️ Șterge</button>
        </div>`}
      </div>`;
      }).join("")
    : `<p>Nicio cazare în această categorie momentan.</p>`;

  const tabHtml = (status, label) => {
    const count = status === "all" ? (counts.pending + counts.approved + counts.rejected) : (counts[status] || 0);
    return `<a href="/admin/cazari?status=${status}" class="admin-tab${activeStatus === status ? " is-active" : ""}">${label} (${count})</a>`;
  };
  const sidebarCounts = await getAdminCounts();

  res.set("Content-Type", "text/html; charset=utf-8");
  res.send(`<!DOCTYPE HTML>
<html lang="ro"><head><meta charset="UTF-8"><title>Cazări — Admin</title>
<style>${adminShellStyles()}</style></head>
<body>
<div class="admin-shell">
${adminSidebarHtml("cazari", sidebarCounts)}
<div style="flex:1">
${adminMobileBarHtml()}
<div class="admin-main">
<h1 class="admin-h1">🏡 Cazări</h1>
<div class="admin-tabs">
  ${tabHtml("pending", "⏳ În verificare")}
  ${tabHtml("approved", "✓ Aprobate")}
  ${tabHtml("rejected", "✕ Respinse")}
  ${tabHtml("all", "Toate")}
</div>
${rowsHtml}
</div>
</div>
</div>
<script>
(function(){${adminSidebarScript()}})();
document.querySelectorAll(".admin-approve-btn, .admin-reject-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    var action = btn.classList.contains("admin-approve-btn") ? "aproba" : "respinge";
    fetch("/api/admin/cazari/" + btn.getAttribute("data-id") + "/" + action, { method: "POST" })
      .then(function(){ location.reload(); });
  });
});
document.querySelectorAll(".admin-repending-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    fetch("/api/admin/cazari/" + btn.getAttribute("data-id") + "/repending", { method: "POST" })
      .then(function(){ location.reload(); });
  });
});
document.querySelectorAll(".admin-delete-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    if (!confirm("Ștergi definitiv \"" + btn.getAttribute("data-name") + "\"? Nu se poate anula.")) return;
    fetch("/api/admin/cazari/" + btn.getAttribute("data-id") + "/sterge", { method: "POST" })
      .then(function(){ location.reload(); });
  });
});
</script>
</body></html>`);
});

app.post("/api/admin/cazari/:id/:action", async (req, res) => {
  if (!requireAdminApi(req, res)) return;
  if (!dbPool) {
    res.status(503).json({ error: "not_configured" });
    return;
  }
  const { id, action } = req.params;
  if (!["aproba", "respinge", "repending", "sterge"].includes(action) || !/^\d+$/.test(id)) {
    res.status(400).json({ error: "invalid_input" });
    return;
  }
  if (action === "sterge") {
    try {
      await dbPool.query(`DELETE FROM accommodation_listings WHERE id = $1`, [id]);
      res.status(200).json({ ok: true });
    } catch (err) {
      res.status(500).json({ error: "server_error" });
    }
    return;
  }
  const newStatus = action === "aproba" ? "approved" : action === "respinge" ? "rejected" : "pending";
  try {
    const { rows } = await dbPool.query(
      action === "aproba"
        ? `UPDATE accommodation_listings SET status = $1, actualizat_la = now(),
             trial_ends_at = COALESCE(trial_ends_at, now() + interval '1 month' * ${ACCOMMODATION_TRIAL_MONTHS})
           WHERE id = $2 RETURNING slug, name, owner_id`
        : `UPDATE accommodation_listings SET status = $1, actualizat_la = now() WHERE id = $2
           RETURNING slug, name, owner_id`,
      [newStatus, id]
    );
    if (action === "aproba" && rows.length) {
      const ownerRes = await dbPool.query(`SELECT email FROM accommodation_owners WHERE id = $1`, [rows[0].owner_id]);
      if (ownerRes.rows.length) {
        const listingUrl = `${baseUrlFor(req)}/cazare/${rows[0].slug}`;
        const loginUrl = `${baseUrlFor(req)}/cazare/autentificare`;
        sendAccommodationApprovalEmail(ownerRes.rows[0].email, rows[0].name, listingUrl, loginUrl).catch((err) => {
          console.error("email de aprobare a eșuat:", err.message);
        });
      }
    }
    res.status(200).json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "server_error" });
  }
});

// ============================================================
// Restaurante/puburi/cafenele — panou de admin, email de aprobare,
// pagină publică. Oglindă exactă a tiparului de la cazare, fără
// abonament (cerut explicit — listare gratuită, punct).
// ============================================================
async function sendRestaurantApprovalEmail(email, listingName, listingUrl, loginUrl) {
  if (!RESEND_API_KEY) { console.error("sendRestaurantApprovalEmail: RESEND_API_KEY lipsă"); return false; }
  try {
    const resp = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { "Authorization": `Bearer ${RESEND_API_KEY}`, "Content-Type": "application/json" },
      signal: AbortSignal.timeout(8000),
      body: JSON.stringify({
        from: "Opening Hours Today <cazare@programul-de-azi.ro>",
        to: [email],
        subject: `Mulțumim! ${listingName} este acum live pe Opening Hours Today 🎉`,
        html: `
<p>Bună,</p>
<p>Vești bune — <strong>${listingName}</strong> a fost verificat și publicat pe Opening Hours Today, gratuit, fără abonament. De acum, oricine caută un loc de mâncat te poate găsi și te poate contacta direct:</p>
<p><a href="${listingUrl}">${listingUrl}</a></p>
<h3 style="margin-top:24px">Ce urmează</h3>
<p>Poți reveni oricând în contul tău ca să actualizezi poze, meniul sau programul:</p>
<p><a href="${loginUrl}">${loginUrl}</a></p>
<div style="margin-top:28px;padding:18px 20px;background:#f7f5f0;border-radius:10px;">
<p style="margin:0 0 10px;font-weight:700;">☕ Un cuvânt despre ce construim aici</p>
<p style="margin:0 0 10px;">Opening Hours Today este un proiect independent, creat special pentru ca unitățile de cazare, restaurantele, cafenelele și obiectivele turistice să aibă vizibilitate maximă, fără taxe ascunse sau comisioane la rezervări. Este spațiul în care tu ții legătura direct cu clienții și oaspeții tăi.</p>
<p style="margin:0 0 14px;">Dacă platforma îți aduce valoare, ne poți ajuta să o menținem activă și gratuită oferindu-ne o cafea. Orice sprijin contează pentru viitorul acestei comunități!</p>
<p style="margin:0"><a href="https://ko-fi.com/openinghourstoday" style="font-weight:700;">☕ Cumpără-ne o cafea →</a></p>
</div>
<p style="margin-top:24px">Îți mulțumim că faci parte din Opening <span style="color:#F0813A">Hours Today</span>.<br>Echipa Opening <span style="color:#F0813A">Hours Today</span></p>`,
      }),
    });
    return resp.ok;
  } catch (err) {
    console.error("sendRestaurantApprovalEmail a eșuat:", err.message);
    return false;
  }
}

app.get("/admin/restaurante", async (req, res) => {
  if (!requireAdminPage(req, res)) return;
  if (!dbPool) { res.status(503).send("Baza de date nu e configurată."); return; }
  const validStatuses = ["pending", "approved", "rejected", "all"];
  const activeStatus = validStatuses.includes(req.query.status) ? req.query.status : "pending";
  let rows = [];
  let counts = { pending: 0, approved: 0, rejected: 0 };
  try {
    const result = await dbPool.query(
      `SELECT l.*, o.email AS owner_email FROM restaurant_listings l
       JOIN accommodation_owners o ON o.id = l.owner_id
       ${activeStatus === "all" ? "" : "WHERE l.status = $1"}
       ORDER BY l.actualizat_la DESC`,
      activeStatus === "all" ? [] : [activeStatus]
    );
    rows = result.rows;
    const countsResult = await dbPool.query(`SELECT status, COUNT(*)::int AS cnt FROM restaurant_listings GROUP BY status`);
    countsResult.rows.forEach((r) => { counts[r.status] = r.cnt; });
  } catch (err) {
    res.status(500).send("Eroare la citirea localurilor: " + escapeHtml(err.message));
    return;
  }
  const statusLabel = { pending: "⏳ În verificare", approved: "✓ Aprobat", rejected: "✕ Respins" };
  const rowsHtml = rows.length
    ? rows.map((r) => {
        const photos = Array.isArray(r.photos) ? r.photos : (typeof r.photos === "string" ? JSON.parse(r.photos) : []);
        const dietary = Array.isArray(r.dietary_options) ? r.dietary_options : (typeof r.dietary_options === "string" ? JSON.parse(r.dietary_options) : []);
        const amenities = Array.isArray(r.amenities) ? r.amenities : (typeof r.amenities === "string" ? JSON.parse(r.amenities) : []);
        return `
      <div class="admin-submission-card">
        <div class="admin-submission-header">
          <span class="admin-submission-type">${escapeHtml(r.venue_type === "altul" && r.venue_type_other ? "📍 " + r.venue_type_other : (RESTAURANT_VENUE_TYPES[r.venue_type] || r.venue_type))}</span>
          <span class="admin-status-tag admin-status-${escapeHtml(r.status)}">${escapeHtml(statusLabel[r.status] || r.status)}</span>
        </div>
        <div class="admin-submission-name">${escapeHtml(r.name)}${r.status === "approved" ? ` — <a href="/restaurant/${escapeHtml(r.slug)}" target="_blank">vezi pagina live ↗</a>` : ""}</div>
        <div class="admin-submission-meta">${escapeHtml(r.address || "")}, ${escapeHtml(r.city)}, ${escapeHtml(r.county)} · ${escapeHtml(r.cuisine || "—")} · ${r.capacity || "?"} locuri</div>
        <div class="admin-submission-meta">L-V ${escapeHtml(r.weekday_open || "—")}–${escapeHtml(r.weekday_close || "—")} · Sâm ${escapeHtml(r.saturday_open || "—")}–${escapeHtml(r.saturday_close || "—")} · Dum ${escapeHtml(r.sunday_open || "—")}–${escapeHtml(r.sunday_close || "—")}</div>
        <div class="admin-submission-meta">Cont: ${escapeHtml(r.owner_email)} · Contact public: ${escapeHtml(r.contact_phone || "—")} / ${escapeHtml(r.contact_email || "—")}</div>
        <div class="admin-submission-meta">Persoană administrare: ${escapeHtml(r.admin_contact_name || "—")} (${escapeHtml(r.admin_contact_role || "—")}) · ${escapeHtml(r.admin_contact_phone || "—")} · ${escapeHtml(r.admin_contact_email || "—")}</div>
        ${dietary.length || amenities.length ? `<div class="admin-submission-meta">${[...dietary.map((d) => RESTAURANT_DIETARY_OPTIONS[d] || d), ...amenities.map((a) => RESTAURANT_AMENITIES[a] || a)].map(escapeHtml).join(" · ")}</div>` : ""}
        ${photos.length ? `<div style="display:flex;gap:6px;flex-wrap:wrap;margin:8px 0">${photos.map((p) => `<img src="${escapeHtml(p)}" style="width:70px;height:70px;object-fit:cover;border-radius:6px">`).join("")}</div>` : ""}
        ${r.logo_url ? `<a href="${escapeHtml(r.logo_url)}" target="_blank" rel="noopener">🏷️ Logo</a><br>` : ""}
        ${r.menu_url ? `<a href="${escapeHtml(r.menu_url)}" target="_blank" rel="noopener">📋 Meniu</a><br>` : ""}
        ${r.website_url ? `<a href="${escapeHtml(r.website_url)}" target="_blank" rel="noopener">🌐 Website</a> ` : ""}
        ${r.facebook_url ? `<a href="${escapeHtml(r.facebook_url)}" target="_blank" rel="noopener">📘 Facebook</a> ` : ""}
        ${r.instagram_url ? `<a href="${escapeHtml(r.instagram_url)}" target="_blank" rel="noopener">📷 Instagram</a> ` : ""}
        ${r.tiktok_url ? `<a href="${escapeHtml(r.tiktok_url)}" target="_blank" rel="noopener">🎵 TikTok</a>` : ""}
        <div class="admin-submission-meta" style="margin-top:8px;border-top:1px solid #333;padding-top:8px">
          <strong>Date fiscale:</strong> ${escapeHtml(r.company_name || "—")} · CUI ${escapeHtml(r.company_cui || "—")} · Reg. Com. ${escapeHtml(r.company_reg_com || "—")}<br>
          GDPR: ${r.gdpr_consent ? "✓ acord dat" : "✕ lipsă"} · Declarant: ${escapeHtml(r.declarant_name || "—")}
        </div>
        ${r.status === "pending" ? `
        <div class="admin-submission-actions">
          <button type="button" class="admin-r-approve-btn" data-id="${r.id}">✓ Aprobă</button>
          <button type="button" class="admin-r-reject-btn" data-id="${r.id}">✕ Respinge</button>
          <button type="button" class="admin-r-delete-btn" data-id="${r.id}" data-name="${escapeHtml(r.name)}">🗑️ Șterge</button>
        </div>` : `
        <div class="admin-submission-actions">
          <button type="button" class="admin-r-repending-btn" data-id="${r.id}">↺ Repune în verificare</button>
          <button type="button" class="admin-r-delete-btn" data-id="${r.id}" data-name="${escapeHtml(r.name)}">🗑️ Șterge</button>
        </div>`}
      </div>`;
      }).join("")
    : `<p>Niciun local în această categorie momentan.</p>`;

  const tabHtml = (status, label) => {
    const count = status === "all" ? (counts.pending + counts.approved + counts.rejected) : (counts[status] || 0);
    return `<a href="/admin/restaurante?status=${status}" class="admin-tab${activeStatus === status ? " is-active" : ""}">${label} (${count})</a>`;
  };
  const sidebarCounts = await getAdminCounts();

  res.set("Content-Type", "text/html; charset=utf-8");
  res.send(`<!DOCTYPE HTML>
<html lang="ro"><head><meta charset="UTF-8"><title>Restaurante — Admin</title>
<style>${adminShellStyles()}</style></head>
<body>
<div class="admin-shell">
${adminSidebarHtml("restaurante", sidebarCounts)}
<div style="flex:1">
${adminMobileBarHtml()}
<div class="admin-main">
<h1 class="admin-h1">🍽️ Restaurante, puburi, cafenele</h1>
<div class="admin-tabs">
  ${tabHtml("pending", "⏳ În verificare")}
  ${tabHtml("approved", "✓ Aprobate")}
  ${tabHtml("rejected", "✕ Respinse")}
  ${tabHtml("all", "Toate")}
</div>
${rowsHtml}
</div>
</div>
</div>
<script>
(function(){${adminSidebarScript()}})();
document.querySelectorAll(".admin-r-approve-btn, .admin-r-reject-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    var action = btn.classList.contains("admin-r-approve-btn") ? "aproba" : "respinge";
    fetch("/api/admin/restaurante/" + btn.getAttribute("data-id") + "/" + action, { method: "POST" })
      .then(function(){ location.reload(); });
  });
});
document.querySelectorAll(".admin-r-repending-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    fetch("/api/admin/restaurante/" + btn.getAttribute("data-id") + "/repending", { method: "POST" })
      .then(function(){ location.reload(); });
  });
});
document.querySelectorAll(".admin-r-delete-btn").forEach(function(btn){
  btn.addEventListener("click", function(){
    if (!confirm("Ștergi definitiv \\"" + btn.getAttribute("data-name") + "\\"? Nu se poate anula.")) return;
    fetch("/api/admin/restaurante/" + btn.getAttribute("data-id") + "/sterge", { method: "POST" })
      .then(function(){ location.reload(); });
  });
});
</script>
</body></html>`);
});

